<template>
<svg viewBox="0 0 800 500" xmlns="http://www.w3.org/2000/svg" font-family="Georgia, 'Times New Roman', serif" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata>
  <rect x="0" y="0" width="800" height="560" fill="#fbf9f4"/>

  <!-- Title -->
  <!-- 
  <text x="400" y="45" text-anchor="middle" font-size="26" 
    font-weight="bold" fill="#2b2b2b">
    Right Triangle Trigonometry
  </text>
  -->

  <!-- Triangle vertices -->
  <!-- 
    A = bottom-left (angle theta), B = bottom-right (right angle), 
    C = top-right 
  -->
  <!-- Using coordinates: A(120,420), B(520,420), C(520,140) -->

  <polygon points="160,320 560,320 560,40" fill="#eaf2fb" stroke="#2b4c7e" 
    stroke-width="3"/>

  <!-- Right angle marker at B -->
  <rect x="535" y="295" width="25" height="25" fill="none" 
    stroke="#2b4c7e" stroke-width="2"/>

  <!-- Angle theta arc at A -->
  <path d="M 210 320 A 30 30 0 0 0 198 293" fill="none" stroke="#b5541e" 
    stroke-width="2.5"/>
  <text x="220" y="310" font-size="22" fill="#b5541e" font-style="italic">
    θ
  </text>

  <!-- Side labels -->
  <!-- Opposite: B to C (vertical, right side) -->
  <text x="570" y="185" font-size="20" fill="#1f7a4d" font-weight="bold">
    Opposite
  </text>
  <text x="570" y="210" font-size="15" fill="#1f7a4d">
    (side b)
  </text>

  <!-- Adjacent: A to B (horizontal, bottom) -->
  <text x="390" y="350" font-size="20" fill="#7a1f5c" font-weight="bold" 
    text-anchor="middle">Adjacent</text>
  <text x="390" y="372" font-size="15" fill="#7a1f5c" text-anchor="middle">
    (side a)
  </text>

  <!-- Hypotenuse: A to C (diagonal) -->
  <text x="370" y="165" font-size="20" fill="#b5541e" font-weight="bold" 
    transform="rotate(-35 330 210)" text-anchor="middle">
    Hypotenuse
  </text>
  <text x="370" y="188" font-size="15" fill="#b5541e" 
    transform="rotate(-35 330 210)" text-anchor="middle">
    (side c)
  </text>

  <!-- Vertex labels -->
  <text x="145" y="340" font-size="18" font-weight="bold" fill="#2b2b2b">
    A
  </text>
  <text x="570" y="340" font-size="18" font-weight="bold" fill="#2b2b2b">
    B
  </text>
  <text x="570" y="30" font-size="18" font-weight="bold" fill="#2b2b2b">
    C
  </text>

  <!-- Formula box -->
  <rect x="70" y="390" width="670" height="70" rx="10" fill="#ffffff" 
    stroke="#c9c2b3" stroke-width="1.5"/>
  <text x="105" y="435" font-size="24" fill="#2b4c7e" font-weight="bold" 
    font-family="Georgia, serif">
    sin θ = opp / hyp
  </text>
  <text x="320" y="435" font-size="24" fill="#1f7a4d" font-weight="bold">
    cos θ = adj / hyp
  </text>
  <text x="525" y="435" font-size="24" fill="#7a1f5c" font-weight="bold">
    tan θ = opp / adj
  </text>

  <!-- Mnemonic -->
  <text x="400" y="490" text-anchor="middle" font-size="15" fill="#555" 
    font-style="italic">
    SOH · CAH · TOA
  </text>
</svg>

</template>
